&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;9dt6b-0-0&quot;&gt;&lt;strong&gt;&lt;span data-offset-key=&quot;9dt6b-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Bonus points&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;public-DraftStyleDefault-ul&quot; data-offset-key=&quot;c8m5s-0-0&quot;&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-reset public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;2sd18&quot; data-offset-key=&quot;c8m5s-0-0&quot;&gt;
