&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-unorderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;ak9na&quot; data-offset-key=&quot;er2h2-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;er2h2-0-0&quot;&gt;&lt;span data-offset-key=&quot;er2h2-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;A genuine bond to Gusto&#39;s mission and the needs of small businesses.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
